package net.civeira.phylax.common.infrastructure.connector.quarkus;

import static org.junit.jupiter.api.Assertions.assertInstanceOf;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import io.opentelemetry.api.OpenTelemetry;
import io.vertx.mutiny.core.Vertx;
import net.civeira.phylax.common.infrastructure.connector.quarkus.mutiny.MutinyWebConnector;

@DisplayName("ConnectorProducer")
class ConnectorProducerUnitTest {

  @Test
  @DisplayName("Should produce a Mutiny web connector")
  void shouldProduceMutinyConnector() {
    Vertx vertx = Vertx.vertx();
    try {
      assertInstanceOf(MutinyWebConnector.class,
          new ConnectorProducer().connector(vertx, OpenTelemetry.noop().getTracer("test")));
    } finally {
      vertx.closeAndAwait();
    }
  }
}
